css:
@font-face {
    font-family: Calibri;
    src: url('/files/Calibri.ttf');
}


/* ================================================================
   BASE PRINT FORMAT
   ================================================================ */

.print-format {
    font-family: Calibri, Arial, sans-serif !important;
    font-size: 12pt;
    box-sizing: border-box !important;
    margin: 0 !important;
    padding: 0 !important;
}

.print-format *,
.print-format *::before,
.print-format *::after {
    box-sizing: border-box !important;
}


/* ================================================================
   DOCUMENT
   ================================================================ */

.print-document {
    width: 100%;
    max-width: 100%;
    margin: 0;
    padding: 0;
}


/* ================================================================
   GENERAL TEXT
   ================================================================ */

p {
    width: auto;
    max-width: 100%;
}

.ql-editor {
    font-family: Calibri, Arial, sans-serif !important;
    font-size: 12pt !important;
    line-height: 1.2 !important;
}


/* ================================================================
   HEADER
   ================================================================ */

.print-header {
    width: 100%;
    margin: 0 0 20px 0;
    padding: 0;
}

.header-flex-container {
    display: flex !important;
    flex-direction: row !important;
    justify-content: space-between !important;
    align-items: flex-start !important;

    width: 100% !important;
    max-width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;
}

.header-logo {
    flex: 0 0 auto;
    width: 55%;
    min-width: 0;
}

.header-logo-img {
    display: block;

    width: 7.28cm !important;
    height: 2.81cm !important;

    max-width: 100% !important;

    object-fit: contain !important;
}

.header-address {
    flex: 0 0 40%;

    width: 40%;
    max-width: 40%;

    text-align: right !important;

    line-height: 1.1;

    overflow-wrap: break-word;
    word-wrap: break-word;
}


/* ================================================================
   DATE / QUOTE NUMBER
   ================================================================ */

.quote-reference-row {
    display: grid;

    grid-template-columns: minmax(0, 1fr) auto;

    column-gap: 15px;

    width: 100%;
    max-width: 100%;

    margin-top: 35px;
    margin-bottom: 25px;

    align-items: start;
}

.quote-date {
    min-width: 0;
    max-width: 100%;

    overflow-wrap: break-word;
    word-wrap: break-word;
}

.quote-number {
    min-width: 0;
    max-width: 100%;

    text-align: right;

    white-space: nowrap;
    overflow-wrap: normal;
    word-break: normal;
}


/* ================================================================
   ADDRESS
   ================================================================ */

.address {
    width: 100%;
    max-width: 100%;

    margin-bottom: 30px;

    line-height: 1.1;

    clear: both;

    overflow-wrap: break-word;
    word-wrap: break-word;
}

.recipient-line {
    margin-bottom: 15px;
}


/* ================================================================
   REFERENCE / LABEL-VALUE ROWS
   ================================================================ */

.reference-row,
.label-value-row {
    display: grid;

    grid-template-columns: 230px minmax(0, 1fr);

    column-gap: 0;

    width: 100%;
    max-width: 100%;

    align-items: start;
}

.alignment-heading {
    width: auto !important;
    min-width: 0;

    margin-top: 1em;
}

.alignment-value {
    width: auto !important;
    min-width: 0;

    margin-top: 1em;

    overflow-wrap: break-word;
    word-wrap: break-word;
}


/* ================================================================
   STANDARD PARAGRAPHS / HEADINGS
   ================================================================ */

p.standard-para {
    margin-top: 1em;
    margin-bottom: 1em;

    line-height: 1.2;
}

.section-heading {
    margin-top: 1em;
    margin-bottom: 0.5em;

    font-style: italic;
    font-weight: bold;
}

.standard-heading {
    margin-top: 1em;
    margin-bottom: 0.5em;

    font-weight: bold;
}

.standard-content {
    width: 100%;
    max-width: 100%;

    overflow-wrap: break-word;
    word-wrap: break-word;
}


/* ================================================================
   LISTS
   ================================================================ */

ul {
    margin-top: 0.5em;
    margin-bottom: 1em;

    padding-left: 25px;
}

li {
    margin-bottom: 0.2em;

    line-height: 1.2;

    overflow-wrap: break-word;
    word-wrap: break-word;
}


/* ================================================================
   JOB DETAILS
   ================================================================ */

.job-details {
    width: 100%;
    max-width: 100%;

    margin-top: 20px;
}


/* ================================================================
   COST SUMMARY
   ================================================================ */

.cost-summary {
    width: 100%;
    max-width: 100%;

    margin-top: 25px;
    padding: 15px;

    background: #f8fafc;

    border-radius: 4px;
}

.cost-row {
    display: grid;

    grid-template-columns: minmax(0, 1fr) 200px;

    width: 100%;
    max-width: 100%;

    align-items: baseline;
}

.alignment-cost-heading {
    min-width: 0;

    padding-right: 10px;

    text-align: right;

    line-height: 1.2;
}

.alignment-cost-value {
    min-width: 0;

    text-align: right;

    line-height: 1.2;

    overflow-wrap: break-word;
    word-wrap: break-word;
}


/* ================================================================
   PAYMENT DETAILS
   ================================================================ */

.payment-details {
    width: 100%;
    max-width: 100%;

    margin-top: 20px;
}

.valid-until {
    margin-top: 10px;
}


/* ================================================================
   SIGNATURE
   ================================================================ */

.signature-section {
    width: 100%;
    max-width: 100%;

    margin-top: 35px;
}

.signature-top {
    margin-top: 1em;
}

.signature-image {
    margin: 10px 0;
}

.signature-img {
    display: block;

    max-height: 2cm;
    max-width: 6cm;

    width: auto;
    height: auto;
}

.signature-name {
    margin-top: 5px;
}

.signature-role {
    color: #666;
    font-size: 0.9em;
}

.customer-signature {
    margin-top: 40px;
    max-width: 300px;
}

.customer-sig {
    margin-top: 20px;
}


/* ================================================================
   HORIZONTAL RULE
   ================================================================ */

hr.solid {
    border-top: 1px solid black;
}


/* ================================================================
   NESTED TABLES
   ================================================================ */

.print-format table {
    max-width: 100%;
}

.print-format table:not(.print-table) {
    width: 100%;
    max-width: 100%;

    border: none;
    border-collapse: collapse;
}

.print-format table:not(.print-table) td {
    max-width: 100%;

    overflow-wrap: break-word;
    word-wrap: break-word;
}


/* ================================================================
   PAGE BREAK
   ================================================================ */

.page-break {
    display: block !important;

    page-break-before: always !important;
    break-before: page !important;

    height: 0 !important;

    margin: 0 !important;
    padding: 0 !important;
}


/* ================================================================
   SCREEN
   ================================================================ */

@media screen {

    html,
    body {
        margin: 0 !important;
        padding: 0 !important;

        background: #fff !important;

        width: 100%;
    }

    .print-format {
        width: 100% !important;
        max-width: 100% !important;

        margin: 0 !important;
        padding: 0 !important;
    }

    .print-document {
        width: 100% !important;
        max-width: 100% !important;

        margin: 0 !important;
        padding: 0 !important;
    }

    .print-footer {
        margin-top: 50px;

        border-top: 1px solid #e2e8f0;

        padding-top: 15px;
    }

}


/* ================================================================
   A4 PAGE SETTINGS
   ================================================================ */

@page {
    size: A4 portrait;

    margin-top: 20mm;
    margin-right: 15mm;
    margin-bottom: 20mm;
    margin-left: 15mm;
}


/* ================================================================
   PRINT / CHROME PDF
   ================================================================ */

@media print {

    html,
    body {
        margin: 0 !important;
        padding: 0 !important;

        background: #fff !important;

        width: 100%;

        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }


    /* ------------------------------------------------------------
       PRINT FORMAT CONTAINER
       ------------------------------------------------------------ */

    .print-format {
        width: 100% !important;
        max-width: 100% !important;

        margin: 0 !important;
        padding: 0 !important;
    }

    .print-document {
        width: 100% !important;
        max-width: 100% !important;

        margin: 0 !important;
        padding: 0 !important;
    }


    /* ------------------------------------------------------------
       MAIN CONTENT
       ------------------------------------------------------------ */

    .quote-body-section {
        display: block !important;

        width: 100% !important;
        max-width: 100% !important;

        page-break-inside: auto !important;
        break-inside: auto !important;
    }


    /* ------------------------------------------------------------
       NATURAL PAGE FLOW
       ------------------------------------------------------------ */

    p,
    div,
    ul,
    ol {
        page-break-inside: auto !important;
        break-inside: auto !important;
    }


    /* ------------------------------------------------------------
       SMALL LOGICAL BLOCKS
       ------------------------------------------------------------ */

    .quote-reference-row,
    .reference-row,
    .label-value-row,
    .cost-row,
    .section-heading,
    .standard-heading {
        page-break-inside: avoid !important;
        break-inside: avoid !important;
    }


    /* ------------------------------------------------------------
       LIST ITEMS
       ------------------------------------------------------------ */

    li {
        page-break-inside: avoid !important;
        break-inside: avoid !important;
    }


    /* ------------------------------------------------------------
       SIGNATURE
       ------------------------------------------------------------ */

    .signature-section {
        page-break-inside: avoid !important;
        break-inside: avoid !important;
    }


    /* ------------------------------------------------------------
       IMAGES
       ------------------------------------------------------------ */

    img {
        max-width: 100% !important;
    }


    /* ------------------------------------------------------------
       LONG CONTENT
       ------------------------------------------------------------ */

    p,
    div,
    td,
    li {
        overflow-wrap: break-word;
        word-wrap: break-word;
    }


    /* ------------------------------------------------------------
       EXPLICIT PAGE BREAKS
       ------------------------------------------------------------ */

    .page-break {
        display: block !important;

        page-break-before: always !important;
        break-before: page !important;

        height: 0 !important;

        margin: 0 !important;
        padding: 0 !important;
    }


    /* ============================================================
       COMPACT FRAPPE PDF FOOTER
       ============================================================ */

    #footer-html {
        width: 100% !important;
        max-width: 100% !important;

        margin: 0 !important;
        padding: 0 !important;

        background: #fff !important;
        border: none !important;
    }


    /*
     * Frappe puts the footer content inside .wrapper.
     *
     * By default the logo/slogan and page number are stacked
     * vertically. This makes the footer unnecessarily tall and
     * reduces the available space for the quote body.
     *
     * Putting both elements on one horizontal line reduces the
     * measured footer height significantly.
     */

    .wrapper {
        display: flex !important;

        flex-direction: row !important;
        align-items: center !important;
        justify-content: space-between !important;
    }


    /* ------------------------------------------------------------
       FOOTER CONTAINER
       ------------------------------------------------------------ */

    .print-footer {
        display: flex !important;

        align-items: center !important;
        justify-content: space-between !important;

        width: 100% !important;
        max-width: 100% !important;

        height: 18px !important;
        min-height: 18px !important;
        max-height: 18px !important;

        position: static !important;

        margin: 0 !important;
        padding: 2px 0 0 0 !important;

        background: #fff !important;

        border-top: 1px solid #e2e8f0;
    }


    /* ------------------------------------------------------------
       FOOTER LOGO + SLOGAN
       ------------------------------------------------------------ */

    .letter-head-footer-flex {
        display: flex !important;

        flex-direction: row !important;
        align-items: center !important;
        justify-content: flex-start !important;

        width: auto !important;
        max-width: 70% !important;

        height: 14px !important;

        gap: 6px !important;

        margin: 0 !important;
        padding: 0 !important;
    }

    .footer-logo {
        display: block !important;

        width: 36px !important;
        height: 14px !important;

        max-width: 36px !important;
        max-height: 14px !important;

        object-fit: contain !important;

        flex: 0 0 auto !important;
    }

    .slogan-text {
        margin: 0 !important;
        padding: 0 !important;

        font-size: 8px !important;
        line-height: 12px !important;

        font-style: italic;

        color: #555;

        white-space: nowrap;
    }


    /* ------------------------------------------------------------
       PAGE NUMBER
       ------------------------------------------------------------ */

    .page-number {
        display: block !important;

        width: auto !important;
        height: 12px !important;

        margin: 0 !important;
        padding: 0 !important;

        text-align: right !important;

        font-size: 8px !important;
        line-height: 12px !important;

        color: #777;

        white-space: nowrap !important;
    }

}
